using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.JNT.Juntas;using GraphApi.Services.JNT.Juntas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.JNT.Juntas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Juntas: creación, actualización y eliminación.")]    public class JuntasMutation    {        [Authorize]        [GraphQLName("createJuntas")]        [GraphQLDescription("Crea un nuevo Junta usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadJuntas> CreateJuntasAsync(            [GraphQLDescription("Datos necesarios para crear el Junta.")]            clCreateJuntas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Junta.")]            IJuntasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateJuntas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateJuntas")]        [GraphQLDescription("Actualiza los campos especificados de un Junta existente.")]        public async Task<clReadJuntas?> UpdateJuntasAsync(            [GraphQLDescription("Datos del Junta a actualizar.")]            clUpdateJuntas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Junta.")]            IJuntasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateJuntas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteJuntas")]        [GraphQLDescription("Elimina un Junta por su ID.")]        public async Task<bool> delJuntasAsync(            [GraphQLDescription("ID del Junta a eliminar.")]            int nJuntasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Junta.")]            IJuntasService objService        )        {            return await objService.DeleteJuntas(nJuntasID);        }    }}